contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function: attempt to transfer ownership to newOwner and observe behavior
    function run(address newOwner) public payable {
        require(newOwner != address(0));

        // Observe owner before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // Attempt the state-changing call and record whether it reverted
        bool reverted;
        c.transferOwnership(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe owner after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General invariant: if the call succeeded then owner equals newOwner; if it reverted then owner is unchanged
        assert((!reverted && ownerAfter == newOwner) || (reverted && ownerAfter == ownerBefore));
    }

    receive() external payable {}
}

